insert into histoire.event_answers(event_id,start_year,start_month,start_day,end_year,end_month,end_day,date_text,description) values
('EVT-0007',1945,4,29,null,null,null,'29 avril 1945 aux municipales','Les Françaises votent pour la première fois lors d''élections municipales. Elles participent désormais au choix des représentants de leur commune.'),
('EVT-0044',800,12,25,null,null,null,'25 décembre 800','Le pape couronne Charlemagne empereur à Rome. La cérémonie affirme son autorité en Occident et montre le rôle de l''Église dans la légitimation du pouvoir.'),
('EVT-0070',1522,9,6,null,null,null,'6 septembre 1522','La Victoria revient en Espagne sous le commandement d''Elcano, après la mort de Magellan. Les survivants achèvent le premier tour du monde par mer et relient concrètement les océans.'),
('EVT-0074',1648,null,null,1653,null,null,'1648-1653','La Fronde rassemble des révoltes contre les impôts et le pouvoir du gouvernement royal. Elle fragilise la monarchie pendant la jeunesse de Louis XIV et oppose plusieurs groupes aux objectifs différents.'),
('EVT-0075',1661,3,10,null,null,null,'10 mars 1661','Après la mort de Mazarin, Louis XIV annonce qu''il gouvernera sans principal ministre. Cette décision affirme sa volonté de contrôler personnellement les affaires du royaume.'),
('EVT-0077',1715,9,1,null,null,null,'1er septembre 1715','La mort de Louis XIV ouvre une succession alors que son héritier Louis XV est encore enfant. Une régence est organisée pour gouverner le royaume en son nom.'),
('EVT-0086',1861,8,17,null,null,null,'17 août 1861','Julie-Victoire Daubié devient la première Française à obtenir le baccalauréat. Son succès ouvre une voie aux femmes dans un enseignement supérieur qui leur reste difficile d''accès.'),
('EVT-0179',1793,1,21,null,null,null,'21 janvier 1793','Louis XVI est exécuté après sa condamnation par la Convention. La mort de l''ancien roi marque une rupture avec la monarchie et accentue les tensions en France et en Europe.'),
('EVT-0287',1961,4,12,null,null,null,'12 avril 1961','Youri Gagarine réalise à bord de Vostok le premier vol spatial humain. La mission démontre la capacité de l''Union soviétique à envoyer un homme en orbite et renforce la compétition spatiale.'),
('EVT-0385',-49,1,10,null,null,null,'10 janvier 49 av. J.-C.','Jules César franchit le Rubicon — repère complémentaire du chapitre « Thème 3 — L’Empire romain dans le monde antique », daté 10 janvier 49 av. J.-C..'),
('EVT-0386',-44,3,15,null,null,null,'15 mars 44 av. J.-C.','Assassinat de Jules César — repère complémentaire du chapitre « Thème 3 — L’Empire romain dans le monde antique », daté 15 mars 44 av. J.-C..'),
