-- LOCAL/CI EXCLUSIVEMENT : 101 événements réemployés, sans joueurs ni comptes.
on conflict(id) do update set title=excluded.title,titre_question=excluded.titre_question,event_type=excluded.event_type,precision=excluded.precision,date_status=excluded.date_status,playable=excluded.playable,playable_mode=excluded.playable_mode,importance=excluded.importance,difficulty=excluded.difficulty,niveau=excluded.niveau,source_status=excluded.source_status;
on conflict(event_id) do update set start_year=excluded.start_year,start_month=excluded.start_month,start_day=excluded.start_day,end_year=excluded.end_year,end_month=excluded.end_month,end_day=excluded.end_day,date_text=excluded.date_text,description=excluded.description;
